 void WeaponTierDetails(Node3D n,int id){if(id==0){Bevel(n,new(.045f,.01f,-.10f),new(.012f,.035f,.16f),Steel);return;}if(id==1){Box(n,new(0,.075f,-.42f),new(.012f,.035f,.02f),Steel);Box(n,new(0,.075f,-.11f),new(.04f,.02f,.03f),Steel);}if(id==2){for(int i=0;i<3;i++)Box(n,new(0,-.03f,.20f+i*.04f),new(.075f,.11f,.012f),Cloth);Tube(n,new(0,-.015f,-.55f),new(0,-.015f,-.70f),.022f,Steel);}if(id==3){Bevel(n,new(0,-.065f,.30f),new(.10f,.17f,.16f),Steel);Box(n,new(0,-.22f,-.12f),new(.055f,.16f,.09f),Ink);for(int s=-1;s<=1;s+=2)Box(n,new(s*.06f,.012f,-.24f),new(.02f,.06f,.20f),Steel);}if(id==4){Tube(n,new(0,-.006f,-.75f),new(0,-.006f,-1.00f),.016f,Steel);Tube(n,new(0,.115f,-.11f),new(0,.115f,-.38f),.037f,Ink);for(int s=-1;s<=1;s+=2)Tube(n,new(s*.02f,-.04f,-.58f),new(s*.07f,-.17f,-.53f),.009f,Steel);}if(id==5){var cyan=new Color(.24f,.59f,.55f);for(int i=0;i<6;i++)Tube(n,new(0,0,-.40f-i*.047f),new(0,0,-.42f-i*.047f),.037f,i%2==0?Steel:cyan);for(int s=-1;s<=1;s+=2){Bevel(n,new(s*.06f,.02f,-.18f),new(.035f,.11f,.20f),Ink);Box(n,new(s*.081f,.025f,-.18f),new(.005f,.025f,.12f),cyan);}Box(n,new(0,.08f,-.15f),new(.06f,.05f,.10f),cyan);}}
 void ItemArmor(Node3D root,int tier,string appearance=""){Color cloth=tier<=2?new(.39f,.35f,.24f):new(.20f,.27f,.27f),plate=tier==1?new(.44f,.38f,.27f):tier==2?new(.30f,.38f,.26f):tier==3?new(.39f,.42f,.40f):tier==4?new(.22f,.31f,.33f):new(.25f,.43f,.43f);if(appearance!="")plate*=.9f+(uint)appearance.GetHashCodeStable()%20/100f;FigureMesh(root,$"items/armor/{tier}/{appearance}",b=>{b.Loft(cloth,new[]{new Vector3(0,0,0),new Vector3(0,.16f,0),new Vector3(0,.36f,0),new Vector3(0,.43f,0)},new[]{new Vector2(.18f,.11f),new Vector2(.18f,.115f),new Vector2(.22f,.13f),new Vector2(.18f,.11f)},20);for(int s=-1;s<=1;s+=2){b.Limb(cloth,new(s*.13f,.37f,-.06f),new(s*.13f,.49f,.07f),.035f,.025f,.035f,.025f,12);b.Panel(plate,new(s*.014f,.08f,-.123f),new(s*.15f,.08f,-.075f),new(s*.18f,.33f,-.105f),new(s*.045f,.36f,-.13f));for(int i=0;i<3;i++)b.Stitch(plate*.6f,new(s*.035f,.13f+i*.06f,-.134f),new(s*.14f,.13f+i*.06f,-.11f),.003f);if(tier>=3)b.Panel(plate*.8f,new(s*.15f,.12f,-.08f),new(s*.21f,.12f,-.01f),new(s*.23f,.27f,-.02f),new(s*.18f,.31f,-.10f));}});if(tier>=4)for(int s=-1;s<=1;s+=2)Bevel(root,new(s*.10f,.15f,-.13f),new(.10f,.11f,.045f),Ink);if(tier==5)for(int s=-1;s<=1;s+=2)Box(root,new(s*.06f,.30f,-.134f),new(.012f,.13f,.01f),new(.32f,.70f,.61f));}
 void ItemMaterial(Node3D n,int m){if(m==0){for(int i=0;i<3;i++){var a=new Vector3((i%2)*.23f-.11f,.12f+(i/2)*.22f,-.32f);Tube(n,a,a+new Vector3(0,.04f,.68f),.12f,Wood);Tube(n,a-new Vector3(0,0,.008f),a-new Vector3(0,0,.014f),.105f,new(.59f,.45f,.27f));}for(int z=-1;z<=1;z+=2)Box(n,new(0,.25f,z*.19f),new(.49f,.035f,.025f),Cloth);}else if(m==1){for(int i=0;i<4;i++)Ellipsoid(n,new((i%2)*.22f-.11f,.12f+(i/2)*.10f,(i/2)*.14f),new(.16f,.12f,.18f),new(.43f,.45f,.40f));}else if(m==2){for(int i=0;i<8;i++)Tube(n,new(-.20f+i*.05f,.06f,-.2f),new(-.18f+i*.05f,.10f,.26f),.025f,new(.58f,.54f,.34f),.018f);for(int z=-1;z<=1;z+=2)Tube(n,new(-.21f,.10f,z*.12f),new(.21f,.10f,z*.12f),.012f,Cloth);}else if(m==3){Tube(n,new(0,.02f,0),new(0,.29f,0),.12f,new(.52f,.31f,.12f));Tube(n,new(0,.28f,0),new(0,.33f,0),.125f,Steel);Box(n,new(0,.15f,-.123f),new(.17f,.12f,.01f),new(.70f,.61f,.37f));}else if(m==4){for(int i=0;i<3;i++){var p=Bevel(n,new((i-1)*.15f,.05f+i*.05f,0),new(.18f,.065f,.48f),Steel);p.RotationDegrees=new(0,i*23-23,0);}for(int i=0;i<2;i++)Tube(n,new(-.19f,.09f+i*.07f,-.17f),new(.24f,.10f+i*.07f,-.10f),.028f,Rust);}else if(m==5){Box(n,new(0,.05f,0),new(.48f,.06f,.36f),new(.15f,.31f,.26f));for(int i=0;i<3;i++){Bevel(n,new((i-1)*.13f,.10f,0),new(.09f,.06f,.15f),Ink);for(int s=-1;s<=1;s+=2)for(int j=0;j<3;j++)Box(n,new((i-1)*.13f+s*.06f,.09f,-.05f+j*.05f),new(.025f,.015f,.015f),Steel);}Tube(n,new(.20f,.07f,.10f),new(.25f,.23f,.15f),.015f,Rust);}else{for(int i=0;i<3;i++){var p=Bevel(n,new((i-1)*.15f,.06f+i*.05f,0),new(.13f,.09f,.42f),new(.24f,.48f,.45f));p.RotationDegrees=new(0,i*8,0);Box(n,new((i-1)*.15f,.11f+i*.05f,0),new(.04f,.008f,.31f),new(.43f,.76f,.63f));}}}
 void ItemSupply(Node3D n,string kind){if(kind=="bandage"){Tube(n,new(-.12f,.12f,0),new(.12f,.12f,0),.12f,new(.70f,.67f,.53f));Tube(n,new(-.125f,.12f,0),new(-.13f,.12f,0),.045f,Wood);Box(n,new(.15f,.035f,.09f),new(.22f,.045f,.19f),new(.65f,.62f,.48f));}else if(kind=="food"){Bevel(n,new(0,.06f,0),new(.38f,.12f,.28f),Cloth);Tube(n,new(.10f,.12f,0),new(.10f,.36f,0),.09f,Steel);Box(n,new(.10f,.23f,-.091f),new(.14f,.13f,.012f),new(.63f,.52f,.27f));}else if(kind=="water"){Bevel(n,new(0,.20f,0),new(.23f,.36f,.13f),new(.25f,.42f,.41f));Tube(n,new(0,.37f,0),new(0,.43f,0),.047f,Steel);Box(n,new(0,.21f,-.071f),new(.17f,.05f,.015f),Cloth);}else if(kind=="bag"){Tube(n,new(-.24f,.14f,0),new(.24f,.14f,0),.14f,Cloth);for(int s=-1;s<=1;s+=2){Tube(n,new(s*.13f,.14f,0),new(s*.13f+.025f,.14f,0),.15f,Wood);Box(n,new(s*.14f,.28f,0),new(.06f,.05f,.05f),Steel);}}else if(kind=="ammo"){Bevel(n,new(0,.09f,0),new(.35f,.18f,.25f),new(.36f,.37f,.24f));for(int i=0;i<5;i++){Tube(n,new(-.13f+i*.065f,.19f,0),new(-.13f+i*.065f,.30f,0),.017f,new(.61f,.48f,.23f),.007f);}}else if(kind=="catalyst"){Tube(n,new(0,.02f,0),new(0,.27f,0),.055f,new(.31f,.61f,.49f));Tube(n,new(0,.26f,0),new(0,.31f,0),.063f,Steel);for(int i=0;i<3;i++)Box(n,new(0,.07f+i*.06f,-.058f),new(.09f,.012f,.014f),Ink);}else{Bevel(n,new(0,.11f,0),new(.40f,.16f,.24f),Ink);for(int i=0;i<3;i++){Tube(n,new(-.12f+i*.12f,.20f,-.04f),new(-.12f+i*.12f,.20f,.09f),.032f,new(.28f,.67f,.55f));}for(int s=-1;s<=1;s+=2)Box(n,new(s*.19f,.1f,0),new(.03f,.08f,.15f),Steel);}}
 void ItemTool(Node3D n,int id){Tube(n,new(0,.06f,0),new(.02f,.70f,0),.023f,Wood);if(id==0){Bevel(n,new(.085f,.67f,0),new(.23f,.14f,.07f),Steel);Bevel(n,new(.19f,.67f,0),new(.035f,.19f,.055f),new(.55f,.58f,.52f));}else if(id==1){Bevel(n,new(0,.075f,0),new(.20f,.18f,.035f),Steel);Tube(n,new(-.06f,.70f,0),new(.06f,.70f,0),.02f,Steel);}else Bevel(n,new(.02f,.66f,0),new(.24f,.095f,.08f),Steel);}
 void ItemModel(Node3D root,string kind,int index=0,int tier=1,string appearance=""){var asset=new Node3D();root.AddChild(asset);switch(kind){case "arrow":for(int i=0;i<5;i++){Tube(asset,new(i*.045f-.09f,.05f,0),new(i*.045f-.09f,.55f,0),.006f,Wood);Bevel(asset,new(i*.045f-.09f,.57f,0),new(.025f,.05f,.02f),Steel);}break;case "medicine":ItemSupply(asset,"bandage");Box(asset,new(0,.15f,-.14f),new(.08f,.05f,.02f),new Color(.7f,.12f,.10f));break;case "attachment":Tube(asset,new(0,.25f,-.25f),new(0,.25f,.25f),.055f,Steel);Bevel(asset,new(0,.18f,0),new(.10f,.05f,.16f),Ink);break;case "weapon":ItemWeapon(asset,index);asset.Scale=Vector3.One*1.2f;asset.Position=new(0,.35f,.30f);asset.RotationDegrees=new(0,65,0);break;case "armor":if(index>=11)ItemAccessory(asset,index,tier);else ItemArmor(asset,tier,appearance);asset.Scale=Vector3.One*1.5f;break;case "material":ItemMaterial(asset,index);asset.Scale=Vector3.One*1.7f;break;case "bench":ArtWorkbench(asset);asset.Scale=Vector3.One*.55f;for(int i=2;i<=tier;i++){Bevel(asset,new(-.50f+(i-2)*.28f,1.1f,.1f),new(.20f,.16f,.18f),i>=4?new Color(.22f,.43f,.42f):Steel);if(i>=4)Box(asset,new(-.50f+(i-2)*.28f,1.18f,-.01f),new(.13f,.08f,.02f),new(.41f,.68f,.59f));}break;case "build":case "structure":asset.AddChild(Structure(new BuildPiece{Kind=index},true));asset.Scale=Vector3.One*.27f;break;case "tool":ItemTool(asset,index);break;default:ItemSupply(asset,kind);asset.Scale=Vector3.One*1.8f;break;}}
 void ItemPreview(VBoxContainer parent,string kind,int index=0,int tier=1,string appearance=""){var container=new SubViewportContainer{CustomMinimumSize=new(240,110),Stretch=true,MouseFilter=Control.MouseFilterEnum.Ignore};parent.AddChild(container);var viewport=new SubViewport{Size=new(360,165),TransparentBg=true,OwnWorld3D=true,RenderTargetUpdateMode=SubViewport.UpdateMode.Always};container.AddChild(viewport);viewport.AddChild(new WorldEnvironment{Environment=new Godot.Environment{BackgroundMode=Godot.Environment.BGMode.Color,BackgroundColor=new Color(0,0,0,0),AmbientLightSource=Godot.Environment.AmbientSource.Color,AmbientLightColor=new Color(.75f,.78f,.73f),AmbientLightEnergy=.65f}});var model=new Node3D{RotationDegrees=new(0,-12,0)};viewport.AddChild(model);ItemModel(model,kind,index,tier,appearance);viewport.AddChild(new DirectionalLight3D{RotationDegrees=new(-35,-35,0),LightEnergy=1.5f,LightColor=new(1,.88f,.69f)});viewport.AddChild(new DirectionalLight3D{RotationDegrees=new(-15,145,0),LightEnergy=.9f,LightColor=new(.68f,.79f,.83f)});var cam=new Camera3D{Position=new(1.1f,.95f,-1.5f),Fov=kind=="bench"?28:22,Current=true};viewport.AddChild(cam);cam.LookAt(new Vector3(0,.35f,0));}
